import{a as e}from"./chunk-2RJSKV3I.js";import{a as n}from"./chunk-WKAGPIYV.js";import"./chunk-U37H3HIF.js";var t=e(n,["한 파일로 합치기","이 파일 빼기(페이지는 보관함으로 가요)","페이지를 여기로 끌어 오세요","이전","고른 페이지를 한 칸 앞으로 옮기기(← 키)","맨 뒤로","고른 페이지를 파일 맨 뒤로 옮기기","이전","다음","파일","뺀 파일과 페이지({n})","뺀 페이지({n})","페이지를 클릭하면 선택되고, Shift-클릭하면 연속으로 선택되고, {mod}-클릭하면 한 장이 추가돼요. 고른 페이지를 끌어 옮기거나 버튼이나 화살표 키를 쓰세요. 페이지를 더블클릭하면 크게 볼 수 있어요.","크게","다음","고른 페이지를 한 칸 뒤로 옮기기(→ 키)","밝기 보정 켜기/끄기","밝기 보정 꺼짐","보통","파일 이름","이름을 숨긴 동안에는 파일 이름을 바꿀 수 없어요","새 파일","새 파일 {n}","페이지 정리…","파일 합치기, 페이지 순서 바꾸기나 빼기","파일 순서","모든 학생에게 이 순서 사용","Word 등 다른 파일은 이 순서대로 페이지 파일 사이에 놓여요.","빼기","고른 페이지 빼기(Delete 키)","{n}쪽","{name}의 {n}쪽을 되돌렸어요","{n}쪽","먼저 페이지를 고르세요",{one:"{n}쪽 선택됨",other:"{n}쪽 선택됨"},"선택한 페이지 없음","제출했을 때 상태로 되돌리기","작게","학생 {n}명이 같은 순서","저장","저장했어요. 내보낼 때 이 순서를 써요.","학생에게 돌려주기","페이지 크기","맨 앞으로","고른 페이지를 파일 맨 앞으로 옮기기","이 페이지 빼기","이 페이지를 빼요. 답안지 아래에 놓이고 '다시 포함'으로 되돌릴 수 있어요.","텍스트","페이지 정리","{name}의 {n}쪽을 뺐어요","뺀 페이지","뺀 페이지는 여기에 모여요.","다시 쓰려면 끌어서 되돌리세요","회전","고른 페이지를 오른쪽으로 90도 회전(R 키)","Word","내 루브릭 페이지",'각 파일은 이 내려받기에서 해당 학생의 제출물에 들어가고 "직접 추가함" 표시가 붙어요. "체크"나 "선택"으로 표시된 것을 확인하세요. 지각 제출로 표시할 학생은 옆의 지각 제출에 체크하세요. 감점은 없어요.',{one:"파일 {n}개를 가져왔지만 여기서 열 수 없어요. 이유는 카드에 있어요.",other:"파일 {n}개를 가져왔지만 여기서 열 수 없어요. 이유는 각 카드에 있어요."},"이 학생에게 같은 이름의 다른 파일이 있어요. 둘 다 남아요.","취소","학생 선택…","{students}에게 {files}을(를) 추가했어요.",{one:"{students}에게 {files}을(를) 추가했어요. {n}개는 지각 제출로 표시했어요.",other:"{students}에게 {files}을(를) 추가했어요. {n}개는 지각 제출로 표시했어요."},{one:"파일 {n}개가 이미 있어서 제외됐어요.",other:"파일 {n}개가 이미 있어서 제외됐어요."},"파일",{one:"파일 {n}개 추가",other:"파일 {n}개 추가"},"지각 제출","모두 지각 제출로 표시","{file}을(를) 지각 제출로 표시","새 학생…","새 학생 이름","추가","새 학생: {name}",{one:"파일 {n}개",other:"파일 {n}개"},"이 파일들은 이미 있어서 새로 추가할 것이 없어요","그곳에 파일이 없어요","이제 면제로 표시됐어요.","이제 미제출로 표시됐어요.",{one:"학생 {n}명",other:"학생 {n}명"},"파일 하나 이상에 학생을 선택하세요","이 파일 건너뛰기",{one:"파일 {n}개, 파일 이름 속 이름 순으로 정렬",other:"파일 {n}개, 파일 이름 속 이름 순으로 정렬"},"체크","선택","직접 선택함","건너뜀","이름으로 연결됨","파일 가져오기","받는 학생","{file}을(를) 받을 학생","이미 작업한 “{name}”이(가) 이 다운로드의 이전 사본일 수 있어요.","가져오기를 누르면 표시와 점수가 이 사본으로 복사돼요. 새로 시작하기를 누르면 이 사본은 비어 있어요. 어느 쪽이든 이전 사본은 남아요.",{one:"파일 {all}개 중 {named}개의 이름이 같고, {n}개는 완전히 똑같아요.",other:"파일 {all}개 중 {named}개의 이름이 같고, {n}개는 완전히 똑같아요."},"더 새로운 사본인가요?","학생 이름과 파일 이름은 일치하지만, 이전 제출물이 여기 저장되어 있지 않아 비교할 수 없어요.","가져오기",{one:"파일 1개가 전에 연 사본과 달라요. 학생 목록에서 !를 찾아보세요.",other:"파일 {n}개가 전에 연 사본과 달라요. 학생 목록에서 !를 찾아보세요."},"늦게 낸 파일, 읽기 자료, Word 수정 내용 중 일부를 옮기지 못했어요. 이전 사본에는 그대로 있어요.","바뀐 파일과 새 파일은 파일 맨 위와 학생 목록의 ! 로 표시돼요.","새로 시작하기",{one:"{name}의 더 새로운 사본인 것 같아요. 학생 {n}명의 표시와 점수를 가져왔어요. 이전 사본은 바뀌지 않았고 홈에 그대로 있어요.",other:"{name}의 더 새로운 사본인 것 같아요. 학생 {n}명의 표시와 점수를 가져왔어요. 이전 사본은 바뀌지 않았고 홈에 그대로 있어요."},"바뀜. 표시가 아직 제자리에 있는지 확인하세요:","파일이 바뀌었거나 이 다운로드에 없어서 Word 수정 내용은 이전 사본에 남아 있어요:","이 다운로드에 없음(작업 내용은 이전 사본에 남아 있어요):","이 학생들의 파일이 바뀌어서 페이지를 원래 순서로 되돌렸어요:","이제 없는 페이지에 표시가 있어요. 이전 사본에는 아직 남아 있어요:","이 다운로드에 새로 들어온 것:","미제출 또는 면제로 표시됐는데 여기에 새 파일이나 바뀐 파일이 있어요. 그 표시가 아직 맞는지 확인하세요:",{one:"새 파일이 있는 학생 {n}명을 지각 제출로 표시",other:"새 파일이 있는 학생 {n}명을 지각 제출로 표시"},{one:"학생 {n}명을 지각 제출로 표시했어요",other:"학생 {n}명을 지각 제출로 표시했어요"},{one:"{pages}쪽의 표시는 이제 이 파일에 해당 페이지가 없어요. 이전 사본에는 남아 있어요.",other:"{pages}쪽의 표시는 이제 이 파일에 해당 페이지가 없어요. 이전 사본에는 남아 있어요."},"지각 제출로 표시","{name}({status}(으)로 표시됨)","지각 제출로 표시했어요. 오른쪽의 '지각'을 누르면 취소돼요.","외 {n}개",{one:"파일 {n}개",other:"파일 {n}개"},{one:"학생 {n}명",other:"학생 {n}명"},{one:"학생 전체 {n}명",other:"학생 전체 {n}명"},"작업한 다운로드","괜찮아요","이 표시 없애기","{name}, {pages}페이지","이번 다운로드에서 바뀜","이번 다운로드에서 새로 생김","이 파일은 이전 사본의 파일과 달라요. 표시는 옮겨 왔으니 제자리에 있는지 확인해 주세요.","이 파일은 이 다운로드의 이전 사본에 없었어요.","작업 내용을 가져왔어요","이 브라우저에 이전 제출물이 저장되어 있지 않아 어떤 파일이 바뀌었는지 확인할 수 없었어요. 한번 훑어보세요.","{name}(학생 전체)","취소","“{text}” 복사함","빈 셀이에요",{one:"항목 {n}개 복사함",other:"항목 {n}개 복사함"},"파일 추가…","{name}에 추가","추가",{one:"{name}에 파일 {n}개를 추가했어요",other:"{name}에 파일 {n}개를 추가했어요"},"다시 포함","{name}을(를) 다시 포함했어요","이런 종류의 파일은 여기서 보여 줄 수 없어요. 내려받아서 여세요.","예시로 사용","학생 찾기","Word에서","뺀 파일 ({n})","제외","{name}을(를) 제외했어요. 다시 포함을 누르면 되돌려요.",{one:"표시 {n}개",other:"표시 {n}개"},"{name} 더 보기","옮기기…","{name} 옮기기","파일이 내 표시가 있는 그대로 그 학생에게 옮겨져요. 이 학생에게 점수나 의견이 있으면 함께 옮길지 물어봐요. 다시 옮겨 올 때도 똑같아요.","{name}을(를) {b} 학생에게 옮겼어요","{name}을(를) {said}와(과) 함께 {b} 학생에게 옮겼어요","{b} 학생에게 이미 이 파일이 있어요","{b} 학생에게 이미 따로 있어서 {a} 학생의 {said}은(는) 그대로 남아요. 덮어쓴 것은 없어요. 이 파일에 속한 것이라면 둘 중 하나를 바꾸세요.","{a} 학생에게 두기",{one:"그 파일에 관한 것이라면 그대로 두세요.",other:"그 파일들에 관한 것이라면 그대로 두세요."},{one:"그 파일에 관한 것이라면 그대로 두세요.",other:"그 파일들에 관한 것이라면 그대로 두세요."},"{b} 학생에게 옮기기",{one:"{a} 학생에게 다른 파일이 {n}개 더 있어요.",other:"{a} 학생에게 다른 파일이 {n}개 더 있어요."},{one:"{a} 학생에게 {said}이(가) 있어요. 이 파일과 함께 {b} 학생에게 옮길까요?",other:"{a} 학생에게 {said}이(가) 있어요. 이 파일과 함께 {b} 학생에게 옮길까요?"},"새 파일","표시 없음","그 이름의 학생이 없어요","이 브라우저에 {name}을(를) 다음을 위해 저장할 수 없었어요. 이 다운로드를 닫기 전까지는 여기 있어요.",{one:"{n}페이지",other:"{n}페이지"},"붙여 넣은 텍스트…","{name}에 추가","이메일로 받은 과제","텍스트를 추가할 수 없었어요: {why}","이름 붙이기","학생이 보낸 내용을 여기에 붙여 넣으세요","페이지에 입력할 수 없는 글자가 있어서 텍스트 사진으로 들어와요. 펜, 형광펜, 의견은 그대로 쓸 수 있어요.","{name} 학생의 텍스트 붙여 넣기","학생이 이메일이나 메시지로 보낸 과제용이에요. 다른 제출물처럼 표시하고, 채점하고, 내보낼 수 있는 페이지가 되어 그 학생의 다른 파일 뒤에 추가돼요. 이 브라우저에만 저장돼요.",{one:"{n}단어",other:"{n}단어"},"이 과제의 Word 제출물 {n}개 모두","앞으로는 과제를 열 때마다 Word 제출물 변환","아직 PDF 페이지를 만드는 중이에요…","변환",{one:"이 Word 제출물이 PDF 페이지가 됐어요",other:"Word 제출물 {n}개가 PDF 페이지가 됐어요"},"이 파일에 입력하거나 칠한 내용은 페이지에 그대로 보여요. 의견에는 번호가 붙고 마지막 페이지 뒤에 목록으로 나와요.",{one:"(입력하거나 의견을 달았거나 채점에 쓴 {n}개는 Word 파일로 남아요)",other:"(입력하거나 의견을 달았거나 채점에 쓴 {n}개는 Word 파일로 남아요)"},"PDF 페이지 만드는 중…","PDF 페이지 만드는 중… {i}/{n}","변환할 것이 없어요",{one:"{n}개는 {max}페이지보다 길거나 그릴 수 없어서 Word 파일로 남아요.",other:"{n}개는 {max}페이지보다 길거나 그릴 수 없어서 Word 파일로 남아요."},"이 파일만","PDF 페이지로 변환","Word 파일이 여느 PDF처럼 어디든 표시하고, 의견을 달고, 도장을 찍을 수 있는 페이지가 돼요. Word 파일 자체는 바뀌지 않고, 제출물 맨 아래 뺀 파일에 남아 다시 포함할 수 있어요.","이 학생의 성적은 이 Word 파일에 입력된 내용에서 가져왔어요. 그 내용은 Word 파일에 남으니, 변환한 뒤 점수 패널에서 점수를 주세요.","변환할 제출물","빼기",{one:"{name}과(와) 그 표시를 뺐어요. 둘 다 제출물 아래 뺀 파일에 남아 있어요.",other:"{name}과(와) 그 표시 {n}개를 뺐어요. 모두 제출물 아래 뺀 파일에 남아 있어요."},"{name}을(를) 뺐어요. 제출물 아래 뺀 파일에 남아 있어요.","바꾸기…","바꾸기","{name}을(를) 바꿨어요",{one:"새 파일이 제출물과 내보내기에서 이전 파일 자리에 들어가요. 점수는 그대로예요. 표시는 다른 페이지로 옮길 수 없어서 이전 파일에 표시가 남아요. 이전 파일은 뺀 파일에 남아 있어서 다시 포함할 수 있어요.",other:"새 파일이 제출물과 내보내기에서 이전 파일 자리에 들어가요. 점수는 그대로예요. 표시는 다른 페이지로 옮길 수 없어서 이전 파일에 표시 {n}개가 남아요. 이전 파일은 뺀 파일에 남아 있어서 다시 포함할 수 있어요."},"이 파일을 바꿀까요?","새 파일이 제출물과 내보내기에서 이전 파일 자리에 들어가요. 점수는 그대로예요. 이전 파일은 뺀 파일에 남아 있어서 다시 포함할 수 있어요.","점수는 그래도 줄 수 있어요.","내가 추가함 \xB7 {d}","{name} 바꿈 \xB7 {d}","텍스트","모든 페이지 돌리기","이 페이지를 왼쪽으로 돌리기","이 페이지를 오른쪽으로 돌리기","성적","의견","“{said}”? 확인","모든 수준 복사","백분율 모두 복사","표로 복사","합계 모두 복사","스프레드시트 다운로드 (CSV)","다름","폴더 순서","점수나 코멘트를 클릭해 복사한 다음 성적부에 붙여 넣으세요. 이름을 클릭하면 그 답안지가 열립니다.","(폴더 없음: 제출 없음)","(제출 없음)","#","명단에 없음","순서","답안지에","답안지 자체에 적힌 성적, 파일에서 읽음","%",{one:"성적 {n}개 \xB7 하나 고르기",other:"성적 {n}개 \xB7 하나 고르기"},"{name} 명단 순서","성적표 (PDF)","상태","학생","합계 /{n}","그룹 점수, 한 명만 조정","표시와 성적 공유","모두","모둠 과제: {name}","완료",{one:"파일 {n}개",other:"파일 {n}개"},"학생 찾기","지금 하는 작업의 대상","✓ 사본 있음","모둠에 포함: {name}","✓ 모둠에 포함","모둠 전체를 한 번에 채점","모두에게 표시 한 벌과 성적 하나","{names}와(과) 함께 한 번에 채점합니다","{name}만","모둠 과제…","모둠이 공유하는 것","이제 그룹 점수가 하나예요. 한 파트너의 점수를 바꾸려면 제출물 위에서 ‘이 학생만’을 고르세요.","이제 그룹 전체가 점수 하나예요","이제 파트너마다 자기 점수와 의견이 있어요. 메모 페이지는 계속 공유돼요.","모두 공유하거나, 모둠에 점수 하나를 주고 한 모둠원만 바꾸거나, 모둠원마다 따로 점수 주기","제출한 것 없음","모둠 전체를 한 번에 채점","채점 표시, 점수, 의견이 모든 파트너의 제출물에 똑같이 보여요. 끄면 한 부씩 따로 채점해요.","따로 채점","이제 {name}은(는) 따로 채점돼요","이 학생에게 따로 성적을 주고 지금까지의 표시를 복사해 줍니다. 나머지는 모둠으로 남습니다.","점수는 각자, 메모는 공유","메모 페이지와 그 위의 표시, 입력한 메모는 계속 함께 써요. 점수와 의견은 파트너마다 따로 줘요.","파트너마다 따로 점수 주기","{name} 학생과 함께 작업한 학생을 하나씩 클릭하세요. 각자 파일 사본을 받으므로, 내보내면 모두가 채점된 제출물을 받아요. 사본에서 빼기를 누르면 되돌려요.","{name} 학생과 함께 씀","페이지 공유 대상",", 각자 따로 채점","모둠 과제","파트너","모두 수정 가능하게 만들기","모두에게 확정된 점수나 이유를 알려 주는 표시가 있습니다.","앞으로 여는 답안지는 자동으로 이렇게 하기","평균","되돌리기",{one:"파일 {n}개를 바꾸지 못했어요.",other:"파일 {n}개를 바꾸지 못했어요."},"면제","이 파일에서는 되지 않았어요. 표시는 원래대로예요.","이 파일은 Grading Studio에서 표시를 페이지에 그려 넣은 채로 내보낸 파일이라 여기서는 바꿀 수 없어요.","바꾸려면 표시를 했던 다운로드를 여세요. 표시는 거기에 남아 있어요. '표시를 수정 가능하게 유지'를 켜고 내보낸 파일은 표시와 함께 돌아와요.",{one:"이 답안지에는 다른 앱에서 한 표시가 {n}개 있어요. 볼 수는 있지만 바꿀 수는 없어요.",other:"이 답안지에는 다른 앱에서 한 표시가 {n}개 있어요. 볼 수는 있지만 바꿀 수는 없어요."},"최고","원본 파일은 바뀌지 않으며, 각 답안지 위의 '되돌리기'로 취소할 수 있어요. 이 코멘트에 적힌 성적은 그대로 반영돼요.","형광펜 표시","코멘트","도장, 그림 및 기타 표시","동그라미와 상자","펜과 선","페이지에 입력한 텍스트",{one:"표시 {n}개(도장이나 그림 등)는 바꿀 수 없어서 페이지에 그대로 남아요.",other:"표시 {n}개(도장이나 그림 등)는 바꿀 수 없어서 페이지에 그대로 남아요."},"지각 제출, 반영됨","내가 평균에서 제외함","이 파일은 잠겨 있어서 표시가 그대로 유지돼요.","답안지를 살펴보는 중… {n}개 중 {i}개","최저","가장 낮음",{one:"수정 가능하게 만들기",other:"수정 가능하게 만들기"},{one:"표시 {n}개를 수정 가능하게 만들기",other:"표시 {n}개를 수정 가능하게 만들기"},"수정 가능하게 만들기","중간 점수","미제출로 표시됨","아직 채점된 루브릭 행이 없습니다.","아직 확정된 점수가 없어 차트로 보일 것이 없습니다.","이 표시들은 어느 것도 수정 가능하게 만들 수 없어서 그대로 유지돼요.","나중에","아직 채점 안 됨",{one:"이제 표시 {n}개를 바꿀 수 있어요.",other:"이제 표시 {n}개를 바꿀 수 있어요."},"답안지에서 읽음, 이 척도에 없음","이 다운로드의 답안지 {n}개에 이런 표시가 있어요.","점수가 합계보다 크거나 0보다 작습니다","일부: 몇 개 행 채점됨","명단에는 있지만 여기엔 없음","반이 가장 어려워한 행","항목별 만점 대비 평균, 낮은 순.","점수 분포","점수, {n}점 만점.","{n}개는 그대로 유지",{one:"학생 {n}명",other:"학생 {n}명"},{one:"답안지 {n}개에 다른 앱에서 한 {marks}이(가) 있어요.",other:"답안지 {n}개에 다른 앱에서 한 {marks}이(가) 있어요."},"이 다운로드에는 수정 가능하게 만들 수 있는 다른 앱의 표시가 있는 답안지가 없어요.","다른 앱의 표시","{n} → 내 형광펜","{n} → 내 여백 코멘트","{n} → 내 타원","{n} → 내 펜","{n} → 내 텍스트","이 과제는 합계만으로 채점해서 비교할 항목이 없어요.","미제출 또는 미완료 학생","처리 중… {n}개 중 {i}개","형성 평가","수업 중","총괄","추가 점수","끝에서 2번째 페이지","끝에서 3번째 페이지","모든 학생","이 페이지와 파일의 나머지","이 스캔 자동 보정","이 페이지 자동 보정","밝기","대비","이 페이지의 밝기 보정을 켜거나 꺼요. 다른 페이지의 ☀를 Shift-클릭하면 그 사이의 모든 페이지에 적용돼요.",{one:"이 페이지의 밝기를 답안지 {n}개의 {page}쪽에 적용했어요",other:"이 페이지의 밝기를 답안지 {n}개의 {page}쪽에 적용했어요"},{one:"이 페이지의 밝기를 다른 {n}쪽에 적용했어요",other:"이 페이지의 밝기를 다른 {n}쪽에 적용했어요"},"글씨 진하게","모든 답안지의 {which}","모든 답안지의 {n}쪽",{one:"답안지 {n}개의 {page} 밝기 보정을 껐어요",other:"답안지 {n}개의 {page} 밝기 보정을 껐어요"},{one:"답안지 {n}개의 {page} 밝기 보정을 켰어요",other:"답안지 {n}개의 {page} 밝기 보정을 켰어요"},"모든 답안지","내보낼 때도 적용","여기서 보이는 모습만 바뀌고, 내보낸 파일은 스캔한 그대로예요.","내보낸 파일에 이 밝기가 적용돼요. 학생의 원본 파일은 바뀌지 않아요.","이 파일의 모든 페이지","흑백","이 페이지만","마지막 페이지","이 페이지는 아직 불러오는 중이에요","밝기 옵션 더 보기","더 보기: 파일의 나머지, 파일 전체, 모든 답안지의 같은 페이지","여기에는 보정할 스캔 페이지가 없어요","끝에서 {n}번째 페이지","끄기","직접 끈 페이지: 이 답안지 {here}, 전체 {n}.","모두 다시 켜기","켜기","{name}만","이 페이지에는 개별 밝기가 있어요(▾로 바꾸기).","개별 밝기: 이 답안지 {here}, 전체 {n}.","모두 나머지와 같게 하기","{n}쪽","밝기 보정 꺼짐","밝기 보정 켜짐","페이지","페이지 모서리의 ☀를 클릭하면 그 페이지만 밝기 보정이 꺼져요. 다른 페이지의 ☀를 Shift-클릭하면 그 사이의 모든 페이지에 적용돼요. ▾로 그 페이지만의 밝기를 정하거나, 파일의 나머지, 파일 전체, 모든 답안지의 같은 페이지에 적용할 수 있어요.","원래대로","이 파일의 나머지","루브릭 설정에서 만든 루브릭","함께 보정","그대로 두기","{n}쪽의 밝기 보정을 껐어요","{n}쪽의 밝기 보정을 켰어요","선명하게","나머지와 같게","그 페이지","이 페이지","밝기 보정을 끌 대상","밝기 보정을 켤 대상","이 페이지의 밝기를 적용할 곳","적용 대상",'파일 이름과 폴더 이름 속 이름으로 연결했어요. "체크"나 "선택"으로 표시된 것을 확인하세요.',"학급","{name}({n})","{students}의 {files} 열기","명단과 맞출 파일…","아직 파일 없음: {names}","먼저 이 학급 페이지에서 명단을 추가한 뒤 다시 해 보세요.","학생",{one:"파일 {n}개",other:"파일 {n}개"},"파일을 학생과 연결","확인","모두 열렸어요: {students}의 {files}. 이상한 점은 없어요.","열 수 없음 ({n})","파일 확인 중…","이름을 클릭하면 그곳으로 갑니다.","이 메시지 닫기",{one:"파일 {n}개",other:"파일 {n}개"},"목록 보기","아직 파일이 없어요.","제출한 것 없음 ({n})","확인 필요 ({n})",{one:"학생 {n}명",other:"학생 {n}명"},"그룹마다 파트너를 고르세요. 점수는 그룹에 하나이며, 동영상이 없는 그룹은 첫 번째 학생의 과제와 표시를 함께 씁니다. 동영상 링크를 붙여 넣거나 동영상 파일을 고르세요. 여기에 동영상 파일을 끌어다 놓으면 파일 이름에 있는 학생에게 들어갑니다.","완료","파일…","이 컴퓨터의 동영상 파일","파트너 점수","{name}의 동영상 링크","동영상 링크 붙여 넣기","이미 그룹에 있음",{one:"이 파일이 어떤 이름과도 맞지 않았어요: {names}. 맞는 줄에서 파일…을 사용하세요.",other:"이 파일들이 어떤 이름과도 맞지 않았어요: {names}. 맞는 줄에서 파일…을 사용하세요."},"점수 하나","각자의 점수","메모는 어느 쪽이든 함께 씁니다.","파트너","{name}의 파트너","같은 동영상:","저장",{one:"그룹 또는 동영상 {n}개를 저장했어요",other:"그룹과 동영상 {n}개를 저장했어요"},"저장 중…","파트너와 동영상","파일 빼기","파트너:","퀴즈 편집…","퀴즈 만들기…","스캔한 퀴즈 가져오기…","표시가 없는 파일도 돌려주기 (Word 파일, 기타 파일, 표시 없는 페이지)","채점된 학생은 모두 이미 먼저 받았어요.","채점 표시 넣는 중 {n}/{of}…","지난번 내보내기가 아직 진행 중이에요. 끝나면 알려 드려요.","폴더에 저장…","이 브라우저에서는 폴더에 저장할 수 없었어요. ZIP 다운로드를 쓰세요.",{one:"완료. 파일 {n}개를 “{dir}”에 저장했어요.",other:"완료. 파일 {n}개를 “{dir}”에 저장했어요."},{one:"완료. ZIP에 파일 {n}개가 있어요.",other:"완료. ZIP에 파일 {n}개가 있어요."},"Google Drive에 저장","완료. Google Drive에서 연 폴더 안의 “{name}”에 저장했어요.","완료. Google Drive에서 연 제출물 옆의 “{name}”에 저장했어요.","완료. Google Drive의 내 드라이브에 있는 “{name}”에 저장했어요.","Google Drive에 저장 중 {n}/{of}…","완료. Google Drive에서 연 ZIP 옆의 “{name}”에 저장했어요.",{one:"먼저 받은 학생 제외",other:"먼저 받은 학생 {n}명 제외"},"표시를 수정 가능하게 유지","나중에 파일을 다시 가져와 표시를 바꿀 수 있습니다. 파일 크기가 약 두 배입니다.",{one:"{when} 내보냄 \xB7 파일 {n}개.",other:"{when} 내보냄 \xB7 파일 {n}개."},"매우 선명",{one:"파일 {n}개를 만들 수 없었어요: {list}.",other:"파일 {n}개를 만들 수 없었어요: {list}."},"각 답안지 앞에 피드백 페이지 넣기","점수, 각 루브릭 행과 그 수준의 뜻, 내 코멘트, 답안지의 코멘트와 페이지 번호.","원본 파일은 바뀌지 않아요. 어디든 표시한 파일은 모든 페이지를 순서대로 통째로 돌려줘요. 의견은 오른쪽 여백에 들어가요.",{one:"학생 {n}명의 파일이 각자의 폴더에 있어 돌려줄 수 있습니다.",other:"학생 {n}명의 파일이 각자의 폴더에 있어 돌려줄 수 있습니다."},"학생별 폴더 유지","각 답안지에 쓴 부호의 범례 추가",{one:"제외한 파일 {n}개는 들어 있지 않아요.",other:"제외한 파일 {n}개는 들어 있지 않아요."},"반환됨으로 표시",{one:"외 {n}개",other:"외 {n}개"},"각 파일에 학생과 과제 이름 붙이기","예: “{name}”. 점수가 있으면 채점됨, 없으면 피드백으로 붙어요.","파일은 제출할 때의 이름을 그대로 씁니다.","내보낼 수 있는 것이 없었어요.","아직 채점한 것이 없어요. 제출물을 채점하면 여기에 보여요.","{d}","학생들이 받으면 돌려줌으로 표시하세요.","학생마다 PDF 하나","{name}의 답안지 내보내기","학생의 모든 답안지를 파일 하나에, 피드백 페이지를 맨 앞에 담습니다. Word 답안지도 페이지가 됩니다. 채점한 Word 루브릭은 계속 Word 파일로 갑니다.","먼저 채점 탭에서 학생의 제출물을 여세요.","{name} 학생의 제출물은 아직 채점하지 않았어요. 채점한 뒤 내보내세요.","“{name}” 저장함.","다른 학생을 기다리지 않고 한 학생에게 채점된 답안지를 지금 돌려줍니다.","한 번에 한 학생",{one:"이 학생의 파일 {n}개를 ZIP 하나로 저장했어요.",other:"이 학생의 파일 {n}개를 ZIP 하나로 저장했어요."},"옵션","성적 읽는 중…",{one:"파일 {n}개 준비됨",other:"파일 {n}개 준비됨"},"{when} 돌려줌.","{when} 내보냄","선명도","성적표 추가(입력한 성적을 하나씩 잘라 낸 것)",{one:"학생 {n}명은 표시한 것이 없어 빠집니다.",other:"학생 {n}명은 표시한 것이 없어 빠집니다."},"표준","오늘 {t}","돌려주지 않음으로 표시","문제가 생겼어요: {why}","ZIP 다운로드","되돌리기","이 페이지는 비어 보여요. '페이지 정리'에서 뺄 수 있어요.","이 페이지를 회전하고 기울기를 바로잡았어요.","다시 스캔한 파일 가져오기…","목록을 복사했어요","목록 복사","이 페이지가 기울어 보여요.","이 페이지는 흐려 보여요.","이제 괜찮아요","괜찮아요","이 페이지를 다시 스캔 필요로 표시","다시 스캔 표시 없애기","다시 스캔 필요로 표시했어요. 확대/축소 옆의 '다시 스캔'에서 기다리는 학생을 모두 볼 수 있어요.","모둠 과제: 이 페이지는 {names}에게도 갔어요. 여기서 한 표시는 이 사본에만 남아요.","왼쪽으로 회전","밝기 보정","{file}의 {n}쪽","이 학생은 밝기 보정이 켜져 있어요.","다시 스캔을 기다리는 페이지가 없어요. 나누기 화면의 '다시 스캔 필요'나 페이지 모서리의 표시로 지정할 수 있어요.","⚑ 이 페이지는 다시 스캔해야 해요. 그래도 표시하고 점수를 줄 수 있어요.","OK","{n}쪽","괜찮아요","오른쪽으로 회전","이 페이지가 옆으로 누워 있을 수 있어요.","바로잡기","이 페이지의 기울기를 바로잡았어요.","다시 스캔이 필요하다고 표시한 페이지예요. 이름을 클릭하면 그 답안지로 가요. 다시 스캔한 파일이 오면 학생에게 추가하거나 '나눌 스캔 파일'로 나눠 넣은 다음, 이전 페이지에서 '이제 괜찮아요'를 누르세요.","회전","바른 방향으로 읽히도록 이 페이지를 회전했어요.","다시 스캔 표시를 없앴어요","이 페이지를 스캔한 그대로 되돌리기","이 페이지가 거꾸로일 수 있어요.","이름 추가","학생 이름","추가",{one:"학생 {n}명에게 페이지를 추가했어요",other:"학생 {n}명에게 페이지를 추가했어요"},"자동 보정","이 페이지를 스캔한 그대로 되돌리기","이 페이지 크게 보기","{n}쪽 \xB7 클릭하거나 Esc를 눌러 닫기","빈 페이지 같아요","빈 페이지 제외","빈 페이지 같아요","이 페이지들을 제외할까요?","제외하기 전에 페이지를 하나씩 확인하세요. 흐린 글씨가 보이도록 여기서는 진하게 보여 주며, 학생의 파일은 바뀌지 않아요. 글씨가 보이면 '이 페이지 남기기'를 누르세요. 페이지를 클릭하면 스캔한 그대로 크게 볼 수 있어요.","'빈 페이지 제외'를 누르면 이 페이지들을 먼저 보여 주고, 어느 것이든 다시 넣을 수 있어요","회전, 기울기 보정함 \xB7 되돌리기","이 페이지를 표시할 수 없어서 남겨 둬요.","학급","닫기","기울었나요? 바로잡기","흐림","채점하려고 열면 이 페이지에서 밝기 보정을 권해요","피드백 중","이름을 입력하고 Enter를 눌러 페이지 주기",{one:"학생 {n}명 \xB7 {of}쪽 중 {given}쪽 배정",other:"학생 {n}명 \xB7 {of}쪽 중 {given}쪽 배정"},{one:"{n}쪽은 아직 아무에게도 배정되지 않았어요(지금 열면 제외돼요)",other:"{n}쪽은 아직 아무에게도 배정되지 않았어요(지금 열면 제외돼요)"},"페이지 없음: {names}",{one:"{n}쪽 다시 스캔 필요",other:"{n}쪽 다시 스캔 필요"},{one:"{n}쪽 공유됨",other:"{n}쪽 공유됨"},"페이지를 준비하는 중…","열어서 채점하기","이 다운로드에 추가","페이지를 클릭한 다음 다른 페이지를 Shift-클릭하면 범위가 선택돼요({mod}-클릭하면 한 장 추가). 페이지를 이름으로 끌어 오거나, 이름을 클릭하거나, 이름을 입력하고 Enter를 누르세요. 그다음부터는 Shift-클릭 한 번으로 다음 페이지부터 클릭한 페이지까지 선택돼요. 페이지를 더블클릭하면 크게 볼 수 있어요. 모둠 과제라면 '여러 명에게 주기'를 켜고 이름을 하나씩 클릭하세요.","나눌 스캔 파일…","{k} / {n}","이 페이지 남기기","모두 남기기","남겨 둠 \xB7 그래도 제외하기",{one:"{n}쪽 제외",other:"{n}쪽 제외"},{one:"빈 페이지 {n}장을 제외했어요",other:"빈 페이지 {n}장을 제외했어요"},"제외됨","채점할 때도 유지: 이 페이지를 받은 학생은 같은 밝기로 열려요","여기와 크게 보기에서 보이는 모습만 바뀌어요. 스캔 자체는 바뀌지 않아요.","이 스캔의 밝기","밝기, 대비, 글씨 진하게, 선명하게, 흑백. 읽기 어려운 페이지에 써요","☀ 밝기","이 페이지는 밝기 보정이 켜져 있어요. 스캔 자체는 바뀌지 않아요.","학생별 답안지를 만드는 중…","다음은 {n}쪽부터 시작: 마지막 페이지를 Shift-클릭하세요","빈 페이지를 찾지 못했어요","일치하는 이름이 없어요.","위에서 학급을 고르거나 이름을 추가하세요.","명단 없음","아직 제출물 없음","선택한 페이지 없음","{name}을(를) PDF로 열 수 없어요","{pages}쪽","{n}쪽",{one:"{n}페이지",other:"{n}페이지"},"먼저 페이지를 고르세요","먼저 제외할 페이지를 고르세요","먼저 다시 스캔할 페이지를 고르세요","고른 페이지","선택됨","고른 페이지({n})",{one:"이 퀴즈는 {n}페이지예요. 코드로 {who}을(를) 찾았어요.",other:"이 퀴즈는 {n}페이지예요. 코드로 {who}을(를) 찾았어요."},{one:"{n}페이지에 이름이 필요해요.",other:"{n}페이지에 이름이 필요해요."},"다시 스캔 필요","⚑ 다시 스캔 필요","고른 페이지를 다시 스캔이 필요하다고 표시해요. 그래도 학생에게 줄 수 있어요.","페이지를 읽는 중… {of}쪽 중 {n}쪽","돌려줄 수 있음","돌려줌","채점 중","{pages}쪽 선택됨","{pages}쪽 선택됨","여러 명에게 주기","여러 명에게 주기가 꺼져 있어요","여러 명에게 주기가 켜져 있어요: 클릭하는 이름마다 고른 페이지에 추가돼요","모둠 과제: 이름을 클릭하면 그 학생이 고른 페이지에 추가되고, 이미 배정된 학생은 그대로 남아요","공유됨","옆으로 누웠나요? 회전","선택한 페이지 제외","아주 흐려요. 글씨일 수도 있고 뒷면이 비친 것일 수도 있어요. '빈 페이지 제외'는 이 페이지를 남겨 두니, 확인해 보고 아무것도 없으면 직접 제외하세요","시작 안 함","아직 페이지를 읽는 중이에요. 잠시 후 다시 해 보세요","기울기 보정함 \xB7 되돌리기","이 페이지 배정 취소","스캔 나누기: {name}","그림으로 바꾸기에 너무 큰 페이지가 있어요. 아무것도 열지 않았어요.","회전함 \xB7 되돌리기","성적만","실행 취소","이 페이지들 배정 취소","다시 스캔 표시 없애기","거꾸로인가요? 회전","스캔 전체",{one:"항목 {n}개",other:"항목 {n}개"},"모음에서 {name} 삭제","모음에서 “{name}”을(를) 삭제했어요. 이미 쓰고 있는 과제는 항목을 그대로 유지해요.","모든 단원","“{name}”을(를) 채웠어요. 남기려면 저장을 누르세요.","이름","단원 없음","이 루브릭을 모음에 저장하면 다시 쓸 수 있어요. 항목, 각 점수의 뜻, 성적 척도가 단원별로 저장돼요. 자료실 > 루브릭에도 같은 모음이 보여요.","이 단원에는 아직 저장된 것이 없어요.","모음에 저장되지 않았어요. 브라우저 공간이 부족할 수 있어요.","문구와 척도만 저장돼요. 점수나 학생에 관한 정보는 절대 저장되지 않아요.","“{name}”을(를) {unit}에 저장했어요. 같은 이름의 것을 대신해요","모음에 저장…","모음에 저장","“{name}”을(를) {unit}에 저장했어요","{n}점 만점","이 척도 저장…","“{name}” 사용 중이에요. 남기려면 저장을 누르세요.","저장한 척도…","루브릭 보기","모음에서 삭제한 루브릭","모음에 저장한 루브릭","모음에 저장한 성적 척도","루브릭 모음","단원","사용","출석",{one:"저장한 날의 기록은 남아 있고, 다시 켜면 다시 보여요.",other:"저장한 {n}일의 기록은 남아 있고, 다시 켜면 다시 보여요."},"Grading Studio에서 출석 확인하기","각 학급의 구성원 탭과 학생 페이지에서 출석을 확인할 수 있어요.","출석 켜기 또는 끄기","{name}의 최저 백분율","등급 {n}","등급별 시작점","각 등급을 받는 최저 백분율이에요. 채점할 때 백분율 옆과 성적 탭에 보여요.","등급 경계","검정","파랑","초록","보라","빨강","모든 코멘트 상자 아래에서 한 번 클릭으로 쓸 수 있고, 최신 것이 맨 위에 있어요. 바꾸거나, 위로 올리거나, 뺄 수 있어요.","새 저장 코멘트","추가","저장한 코멘트","저장한 코멘트 {n}","아직 저장된 것이 없어요. 채점하는 동안 코멘트 상자에서 저장하거나 여기서 추가하세요.","빼기","저장한 코멘트를 뺐어요","저장한 코멘트를 추가했어요","저장한 코멘트를 바꿨어요","저장한 코멘트를 옮겼어요","저장한 코멘트를 뺐어요","위로","Word 문서: 글자 크기","채점 화면용이에요. 이 컴퓨터에 저장돼요.","제출물과 글자","Word 문서: 줄 간격","보통","넓게","좁게","Enter로 다음 채점할 답안지로 이동","제출물","페이지 전체 보기","너비에 맞추기","부터","✓ 정답","✗와 펜","✗와 펜, 체크, 제출물에 쓰는 점수의 색이에요. 새 표시에 적용돼요. 이 컴퓨터에 저장돼요.","표시 색","학생 목록 항상 보이기","이 컴퓨터의 메일 앱","Gmail","이메일 열기","웹용 Outlook","이메일 버튼이 메시지를 여는 곳이에요. 직접 보내기 전에는 아무것도 보내지지 않아요. 휴대폰에서는 휴대폰의 기본 메일 앱이 열려요.","돌려주는 파일마다 끝에 한 페이지를 붙여, 그 파일에 쓴 교정 부호와 문장 부호만 뜻과 함께 보여 줘요. 스티커와 체크 표시는 빠져요. 뜻을 비워 두면 이름만 보여요.","첨삭 기호","뜻","이 표시의 이름","돌려주는 답안지에 범례 넣기","교정 부호","문장 부호","원래 문구로 되돌리기","이름은 가림 확인에서 직접 가려요. 자동으로 찾으면 이름이 아닌 단어까지 가릴 수 있어요.","입력된 이름도 찾기","이름 가리기","이름을 직접 가리기","{n} pt","득점에 따라","만점: 2/2 \xB7 부분 점수: 1/2 \xB7 없음: 0/2. 합계와 점수 도장은 빨간색 그대로예요.","점수","✗와 같게","{n} px","새 과제에 적용돼요. 어느 루브릭이든 루브릭 설정에서 다른 척도를 쓸 수 있어요.","새 루브릭은 항목마다 {how}(으)로 채점해요.","0.5점 단위","루브릭 항목마다 0점부터","등급 경계","평소 항목 척도","단원 계획 도구 이름","평소 평가 방식","제출물에 넣는 새 텍스트 상자","각 단원의 계획 링크에 표시되는 말이에요. 예를 들어 학교에서 쓰는 단원 계획 도구의 이름이요. 화면에 보이는 글자일 뿐, 그 도구와 연결되지는 않아요.","이제 단원 계획 링크에 {name}(이)라고 표시돼요.","내 설정","단원 계획 도구 이름","이제 단원 계획 링크에 단원 계획이라고 표시돼요.","새 과제의 기본 방식이에요. 어느 과제든 루브릭 설정에서 다른 방식으로 채점할 수 있어요.","이제부터 새 과제는 {way}(으)로 시작해요. 기존 과제는 각자의 설정을 유지해요.","평소 평가 방식","IB DP 1~7","디플로마처럼 백분율에서 1~7의 최종 성적을 계산합니다. 과목에 맞게 경계를 정합니다.","등급(A~F)","백분율에서 A~F를 계산합니다. 각 등급의 시작점은 직접 정합니다.","IB MYP 평가 기준","각 기준을 0~8로 평가합니다. 가장 잘 맞는 수준을 고르면 합계가 1~7의 최종 성적이 됩니다.","선택 안 함: 새 과제는 지금까지처럼 루브릭 세 줄과 12점 척도(12 = 100, 11 = 95, 10 = 91…)로 시작합니다. 하나를 선택하면 그 뒤에 만드는 과제만 바뀝니다.","백분율","제출물마다 백분율을 입력합니다.","점수","20점 만점에 17점처럼 합계를 입력합니다. 만점은 과제마다 따로 정합니다.","루브릭 항목","각 항목을 0에서 4까지, 0.5점 단위로 채점합니다. 합계와 백분율은 자동으로 계산됩니다.","접으면 학생 목록이 점수 띠로 바뀌어요. 채점하는 동안 [ 키로 펼치거나 접을 수 있어요. 입력란에 입력하는 중에는 Enter를 눌러도 넘어가지 않아요.","채점하는 동안","{n}번의 평균","{n}번 중 최고 점수","가장 최근 시도","바꾸기","반영: {pct}, {how}","지각","이 점수 더 보기","재응시 취소","재응시를 취소했어요. 점수가 다시 {name}(으)로 돌아가요.","평균에서 제외","다시 포함","평균에서 제외됨.","백분율 점수","백분율","이 점수가 그대로 유지됩니다. 루브릭 행을 바꿔도 달라지지 않습니다.","점","평균","시도들의 평균 반영","최고","가장 잘한 시도 반영","최근","더 낮더라도 가장 새로운 시도 반영","빼기","재응시 시작","먼저 이 제출물에 점수를 모두 주세요. 재응시는 그 점수를 남기고 새로 시작해요.","재응시","{name} 유지: {score}. 재응시 점수는 여기서 주세요.","{name} 유지: {score}. 재응시 점수는 여기서 주고, 그 제출물은 추가로 넣으세요.","재응시 한 번 더","모든 과제에서 반영할 시도","재응시: 모든 과제에서 {how}.","첫 번째 시도","{n}번째 시도","재응시 점수가 모두 채워질 때까지는 첫 번째 시도가 반영돼요: {pct}","재응시 점수가 모두 채워질 때까지는 이전 시도들이 반영돼요: {pct}","추가 점수","추가 점수 반영","추가 점수","추가 점수 백분율","추가 점수","항목 추가","제출물 뒤","이 파일을 Word 파일, PDF, 사진으로 열 수 없었어요","앞","쓰지 않는 행은 비워 두세요. 0.5점은 두 행 사이에 들어갑니다.","내 루브릭 가져오기…","취소","각각 따로","5 단위 (9 = 85%)","항목을 찾았습니다.","전체 점수의 학습 목표","목표 편집…","뺀 목표","새 목표…","선택: 반과 학생을 목표별로 봐요.","이 항목의 학습 목표","행에 학습 목표 달기…","이 점수에 학습 목표 달기…",{one:"학생 1명이 뺀 항목에 점수가 있어요. 그 점수는 항목과 함께 사라지고 합계가 바뀌어요.",other:"학생 {n}명이 뺀 항목에 점수가 있어요. 그 점수들은 항목과 함께 사라지고 합계가 바뀌어요."},"0.5점 단위","이 과제는 어떻게 채점하나요?","행 이름을 바꿔도 이미 매긴 점수는 그대로입니다.","항목 이름을 바꿔도 이미 준 점수는 그대로예요. 이 설정은 “{name}”에 기억돼요.","각 점수의 뜻","어느 칸이든 비워 둬도 돼요.","어느 칸이든 비워 둬도 돼요. 0.5점이면 앞뒤 두 점수의 설명이 보여요.","각 점수의 뜻 ({of}개 중 {n}개 작성)","이 행에서 {v}의 뜻","목표 없음","척도 없음","척도 없음: 백분율은 얻은 점수의 비율 그대로예요.",{one:"학생 1명에게 이 척도에 없는 점수가 있어요. 바꾸기 전까지 그대로 남고 계속 계산에 들어가요.",other:"학생 {n}명에게 이 척도에 없는 점수가 있어요. 바꾸기 전까지 그대로 남고 계속 계산에 들어가요."},"전체 {n}점 만점.","만점","모든 학생을 위한 내 루브릭","루브릭 페이지","루브릭을 한 번만 가져오면 학생마다 채점할 사본이 생겨요. Word 루브릭(DOCX 또는 DOCM)은 Word 파일 그대로라서 입력하고, 체크 상자에 표시하고, 셀을 칠할 수 있어요. PDF나 사진은 표시할 수 있는 페이지로 추가돼요. 각 사본은 그 학생의 제출물과 함께 돌려줘요.","빼기","바꾸기…","{n}번째 항목","평가 기준 {n}","{n}번째 항목 빼기","루브릭 항목",{one:"학생 1명에게 루브릭 항목 점수가 있어요. 저장은 되어 있지만 합계만 쓰는 동안에는 계산되지 않아요.",other:"학생 {n}명에게 루브릭 항목 점수가 있어요. 저장은 되어 있지만 합계만 쓰는 동안에는 계산되지 않아요."},"저장","루브릭 설정을 저장했어요","성적 척도","이 루브릭 파일은 너무 커서 저장할 수 없어요. 더 작은 PDF나 스크린샷을 써 보세요.","척도의 합계는 40 이하여야 해요.","각 행의 점수 범위: 0부터","합계만","내 루브릭에 바로 채점하나요? 합계만을 쓰면 점수 칸이 하나이고, 성적 탭과 백분율도 그대로 작동합니다.",{one:"학생 1명에게 직접 입력한 합계가 있어요. 저장은 되어 있지만 루브릭 항목을 쓰는 동안에는 계산되지 않아요.",other:"학생 {n}명에게 직접 입력한 합계가 있어요. 저장은 되어 있지만 루브릭 항목을 쓰는 동안에는 계산되지 않아요."},"이 항목 사용","12 = 100, 11 = 95, 10 = 91…","넣을 위치","요청한 길이(분)","계속","요청한 길이 안","최소","최대","요청한 것보다 김","일시정지","초기화","타이머의 시간을 [2:15]처럼 코멘트에 넣습니다","시작","타이머","요청한 것보다 짧음","이 과제에서는 입력 메모를 나만 가지고 있어요","이 과제에서는 입력 메모가 각 제출물과 함께 돌아가요","이 학생의 입력 메모를 지웠어요","메모를 복사했어요","메모가 없는 학생은 다시 빈 페이지로 시작해요",{one:"아직 메모가 없는 학생은 모두 제목 {n}개로 시작해요",other:"아직 메모가 없는 학생은 모두 제목 {n}개로 시작해요"},"이 시간은 타이머에서 온 것입니다. 이동할 동영상이 없습니다.","이 브라우저에서는 복사가 되지 않았어요.","크게","표준","메모 페이지는 {size} 글자로 돌아가요","작게","시간을 숨겼습니다. 모든 시간 표시로 되돌릴 수 있습니다.","시간을 다시 표시했습니다","단원 추가","새 단원","취소","단원 삭제","이 단원에는 아직 과제가 없어요.","'{name}'을(를) 삭제했어요",{one:"'{name}'과(와) 과제 {n}개를 삭제했어요",other:"'{name}'과(와) 과제 {n}개를 삭제했어요"},"{name} 더 보기","{name} 더 보기","옮기기…","'{name}' 옮길 곳","{name}(으)로 옮겼어요","단원 이름","단원 {n}","학급 없음","이름 바꾸기","단원 이름 바꾸기","동영상 또는 녹음…","{name}의 동영상","{name}에게 동영상을 추가했어요","10초 앞으로","오디오","10초 뒤로","웹 주소가 아니에요","동영상 파일","A 링크","동영상 아래 자막","지금 말하는 문장을 동영상 아래에 바른 방향으로 보여 줘요","사이트 자체 자막은 동영상과 함께 회전해요. 자막을 바른 방향으로 보려면 아래에 대본을 붙여 넣고 동영상 아래의 '자막'을 켜세요.","동영상 파일 선택…","플레이어 닫기","링크를 복사했어요","링크 복사","편집","이 동영상을 추가할 수 없어요: {why}","동영상 파일","이 컴퓨터의 이 브라우저에 저장되며, 공간만 있으면 길이에 제한이 없어요. 학생에게 돌려주는 파일에는 들어가지 않아요.","띄우기","채점하는 동안 맨 위에 떠 있는 작은 창에서 동영상을 재생해요","{name}에게 이미 이 동영상이 있어요","5초 앞으로","5초 뒤로","녹화 재생 또는 일시 정지","동영상 링크","여기에는 링크만 저장되고 동영상은 원래 자리에 있어요. 로그인을 요구하거나 재생되지 않으면 새 창에서 여세요.","여기에는 링크만 저장돼요. 이 사이트는 페이지 안에서 재생할 수 없어서 별도 창에서 열려요.","https://","여기에는 링크만 저장되니, 동영상은 원래 자리에 있고 느려지지도 않아요.","발표 동영상","링크를 복사할 수 없어요","이 동영상은 이 브라우저에 없어요. 다른 브라우저나 다른 컴퓨터에 저장한 동영상 파일은 과제와 함께 옮겨지지 않아요.","동영상이나 소리 파일이 아니에요","나중에","{name}에게 추가","{name}에게 메모 페이지를 추가했어요","빈 페이지","제목만","두 칸","잘된 점과 노력할 점","이 페이지를 추가할 수 없어요: {why}","메모 페이지","줄 있음","줄과 시간을 적는 여백","메모 페이지…","이름 정하기","메모","없음","이 과제에는 루브릭 항목이 없습니다","루브릭 항목","루브릭 항목마다 칸 하나","보면서 적는 페이지예요. 답안지처럼 채점하고, 점수를 주고, 돌려줘요.","{name}의 메모 페이지","발표, 연설, 공연 등을 보거나 들으면서 적는 페이지예요. 펜으로 쓰거나 입력한 다음, 답안지처럼 점수를 주고 돌려주세요.","새 창에서 열기","동영상을 별도 창에서 열어 이 창 옆에 둘 수 있어요","동영상을 여는 중…","또는 여기에 끌어다 놓기","여기서 재생","빼기","이 컴퓨터에 동영상을 저장할 공간이 없어요. 공간을 확보하거나 동영상 링크를 대신 쓰세요.","저장","끌어서 동영상 높이 조절","속도","+ 시간을 코멘트에","코멘트에 시간을 넣어요. 예: [2:15]","코멘트에 시간을 넣었어요","대본","다시 만들기","대본을 만들려면 이 브라우저가 음성 인식 엔진(약 150 MB)을 한 번 내려받아요. 그다음에는 인터넷 없이도 작동해요. 동영상은 이 컴퓨터에 남고, 아무것도 업로드되지 않아요.","대본 바꾸기","저장할 텍스트가 없어요","내려받고 대본 만들기","1:05나 [00:01:05]처럼 시간으로 시작하는 줄은 그 시점부터 동영상을 재생해요. 자막 파일(.srt, .vtt)도 붙여 넣을 수 있어요. 내용은 이 브라우저에 저장돼요.","이 브라우저에서 만듦","대본 만들기","말하는 내용을 이 브라우저에서 받아 적어요. 문장을 클릭하면 거기서부터 재생돼요.","이 브라우저에서 만들며, 아무것도 업로드되지 않아요. 만드는 동안 계속 채점해도 되지만, 이 학생은 열어 두세요.","대본을 없앴어요","대본 붙여 넣기","가지고 있는 대본을 붙여 넣어요. 예를 들어 AI 도우미로 만든 대본이나 동영상 자체 자막이요","붙여 넣음","대본이 준비됐어요. 문장을 클릭하면 거기서부터 재생돼요.","Google Drive 등 다른 사이트는 이 페이지에 자막을 넘겨주지 않아요. 가지고 있는 자막을 붙여 넣으세요.","시작하는 중…","멈췄어요. 대본을 만들지 않았어요.","옆으로 촬영된 동영상을 90도 회전합니다","동영상","동영상","더 새로운 사본 가져오기","더 새로운 사본(파일 또는 ZIP)…","더 새로운 사본(폴더)…","{d}에 돌려줌","제출물 가져오기","{d}에 가져온 제출물","다운로드한 파일, ZIP, 폴더를 과제 위에 끌어다 놓아도 돼요.","마감: {d}","돌려줌 {sent}/{of}",{one:"학생 {n}명이 먼저 받았어요",other:"학생 {n}명이 먼저 받았어요"},"먼저 받은 학생(한 명씩 돌려줌)","이 제출물들은 가져올 수 없었어요.","{of}개 중 {done}개 피드백 완료","파일 또는 ZIP…","폴더…","성적","분석","제출물이 이 브라우저에 저장되어 있지 않아요","{name} 자세히 보기","이 학급에는 아직 과제가 없어요.","끌어다 놓은 것에서 아무것도 찾지 못했어요",{one:"미제출 또는 면제 {n}개",other:"미제출 또는 면제 {n}개"},"열기",{one:"채점 중 {n}개",other:"채점 중 {n}개"},"돌려주기","나눌 스캔 파일…","{of}개 중 {done}개 채점됨","과제","원본으로 되돌리기","글자를 클릭하면 입력할 수 있어요. 표 셀을 클릭한 뒤 색을 고르면 칠해져요:","클릭해서 이 점수 강조(이웃한 두 칸 = 0.5점)","이 Word 파일은 여기서 열 수 없었어요. 내려받아서 Word로 여세요.","먼저 표 셀을 클릭하세요","이 표의 합계는 {a}인데 이 과제는 {b}점 만점이에요. 학급 전체를 {a}점 만점으로 바꾸고 이 파일의 성적 척도를 쓸까요?","아니요, 그대로 두기","이 표의 합계는 {a}인데 이 과제는 {b}점 만점이에요. 학급 전체를 {a}점 만점으로 바꿀까요?","이 파일에는 자체 성적 척도가 있는데, 이 과제에서 쓰는 척도와 달라요. 학급 전체에 쓸까요?","네, 학급 전체","의견","단어를 선택한 뒤 이 버튼을 누르면 의견을 달 수 있어요. 아니면 의견 도구를 고르고 단어를 클릭하세요.","파일 속 의견","편집 완료","내려받기","평가 기준마다 점수 칸을 하나씩 클릭하세요","편집","파일을 바꾸려면 먼저 편집을 클릭하세요","내가 수정함","Word 파일 편집 중","Word 파일","매크로가 있는 Word 파일","매크로는 브라우저에서 실행되지 않지만 파일에 남아 있어서 Word로 열면 다시 작동해요.","이 루브릭은 {a}점 만점인데 루브릭 설정은 {b}점 만점이라 점수 패널과 맞지 않아요. 이 루브릭으로 채점하려면 루브릭 설정에서 합계만을 고르세요.","이 Word 파일의 의견을 읽을 수 없어서 여기서 새 의견을 달 수 없어요. 내려받아서 Word에서 의견을 다세요.","이 브라우저에 원본이 저장되어 있지 않아요","색 없음","이 브라우저에 수정 내용을 저장할 수 없었어요. 남기려면 파일을 내려받으세요.","원본으로 되돌리기","PDF로 변환","이 파일을 PDF처럼 어디든 표시하고 의견을 달 수 있는 페이지로 바꿔요. Word 파일은 남아요.","단어를 오른쪽 클릭해서 의견 달기","내 루브릭","이걸로 채점","의견을 달 단어를 선택한 뒤 의견을 누르세요. 아니면 의견 도구를 고르고 단어를 클릭하세요.","셀 칠하기: {c}","이 파일의 표가 점수 루브릭일 수 있어요."],null);export{t as default};
